pub enum AuthorFactsLeaf {
    ViewerIsAuthor,
    IsSelfQuote,
}

impl Leaf for AuthorFactsLeaf {
    type Feature = AuthorFacts;

    #[inline]
    fn meaning<'a, M: Meaning<'a, AuthorFacts>>(self, m: M) -> M::Out {
        match self {
            Self::ViewerIsAuthor => m.run(|author, facts| facts.viewer_id() == Some(author)),
